const c=[{id:"P01",title:"Steel · 2007 · Relaciones y teoría de la procrastinación",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"691 correlaciones de 216 trabajos relacionaron la procrastinación con tareas desagradables, menor autocontrol y menor confianza para hacerlas. La intención de trabajar tuvo r = -0.03, con un intervalo que incluía cero.",limitation:"Evidencia correlacional, principalmente de estudiantes. No demuestra causas ni permite diagnósticos individuales. Las estimaciones antiguas de frecuencia no representan las tasas actuales."},{id:"P02",title:"Sirois y Pychyl · 2013 · Alivio emocional a corto plazo",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"Un modelo teórico explica cómo evitar las emociones desagradables de una tarea puede aliviarte ahora y dejarte costos para después.",limitation:"Revisión narrativa sin un nuevo efecto combinado. No explica todas las demoras ni demuestra que nombrar una emoción cambie la conducta."},{id:"P03",title:"Gollwitzer y Sheeran · 2006 · Metaanálisis de planes si-entonces",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"En 94 pruebas independientes, los planes concretos si-entonces mejoraron, en promedio, el logro de metas. El efecto estandarizado histórico fue d = 0.65.",limitation:"Estudios antiguos y variados. No significa un 65 por ciento más de éxito ni un efecto específico sobre procrastinación. El ejercicio breve de ODA no se evaluó."},{id:"P04",title:"Wang, Wang y Gai · 2021 · Contraste mental y planificación",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"21 artículos y 24 efectos mostraron un beneficio promedio pequeño a moderado para lograr metas al combinar contraste mental y planes si-entonces.",limitation:"Las diferencias entre estudios y señales de sesgo de publicación limitan la magnitud estimada. La adaptación breve de ODA no se evaluó. Puede convenir abandonar metas inviables."},{id:"P05",title:"Rozental y colaboradores · 2018 · Intervenciones controladas sobre procrastinación",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2018.01588/full",type:"research",finding:"12 estudios con 718 participantes encontraron una reducción promedio modesta de la procrastinación declarada, frente a controles sin intervención activa.",limitation:"Principalmente estudiantes, métodos variados, problemas de calidad y pocos estudios por tratamiento. Son hallazgos provisionales: no demuestran la eficacia de ODA ni una clasificación universal de tratamientos."},{id:"P07",title:"Wohl, Pychyl y Bennett · 2010 · Perdonarse y procrastinación",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 estudiantes de primer año, evaluados antes de dos exámenes parciales, mostraron una relación entre perdonarse más y postergar menos el estudio del examen posterior.",limitation:"Un grupo de un solo curso, con diseño observacional. No se demostró que una frase causara cambios ni que se repararan consecuencias. El reclutamiento inicial y los abandonos siguen sin verificarse."},{id:"P08",title:"Han y Kim · 2023 · Revisión de intervenciones de autocompasión",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"En 56 ensayos aleatorizados, las intervenciones de autocompasión mostraron beneficios inmediatos pequeños a moderados en medidas de malestar, con limitaciones.",limitation:"Riesgo general de sesgo alto, programas diversos y pocas comparaciones activas. No hay evidencia aquí de que una sola frase trate la ansiedad o reduzca la procrastinación."},{id:"P09",title:"Zhou y colaboradores · 2026 · Planificación y disposición a empezar",url:"https://pubmed.ncbi.nlm.nih.gov/41601124/",type:"research",finding:"Un estudio aleatorizado con 81 universitarios informó tareas menos desagradables y mayor disposición a actuar con MCII, frente al pensamiento positivo.",limitation:"Una universidad privada china y seguimiento breve. El resumen no verifica finalización objetiva, porcentajes de inicios diarios, abandonos ni registro previo del estudio."},{id:"P10",title:"Oettingen y colaboradores · 2015 · Procedimiento para planear el tiempo",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Un ejercicio académico de MCII combinó resultado deseado, obstáculo, respuesta, momento y lugar, ensayo y calendario semanal. Se midieron horas de actividad previstas.",limitation:"El estudio 1 asignó al azar a 84 universitarios alemanes. Midió planificación, no trabajo realizado. La adaptación de ODA para tareas adultas cambia el procedimiento."},{id:"P11",title:"Biwer y colaboradores · 2023 · Pausas fijas y elegidas",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 estudiantes compararon pausas elegidas con horarios 24/6 y 12/3. Los horarios fijos tuvieron beneficios subjetivos; no se informó una diferencia significativa en tareas terminadas.",limitation:"Un solo día de estudio autónomo y muestra pequeña; acceso únicamente al resumen. No hallar significación no demuestra igual producción, reducción duradera de procrastinación ni un horario 25/5 óptimo."},{id:"P12",title:"Albulescu y colaboradores · 2022 · Revisión de pausas breves",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"En 22 muestras, las pausas breves mostraron beneficios promedio más claros para el cansancio y la energía que para el rendimiento general.",limitation:"Tareas y actividades durante las pausas muy diversas. No se estableció un horario 25/5 óptimo ni una mejora fiable del rendimiento en tareas exigentes."},{id:"P13",title:"Harkin y colaboradores · 2016 · Metaanálisis de seguimiento del progreso",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Las intervenciones de seguimiento mejoraron, en promedio, el logro de metas en 138 estudios aleatorizados.",limitation:"Metas y métodos diversos. Los análisis de registro y comunicación no prueban causalmente cada formato. No se exige compartir públicamente ni revisar dos minutos por semana."},{id:"P15",title:"Psychological Science · 2026 · Retractación del artículo sobre plazos",url:"https://journals.sagepub.com/doi/full/10.1177/09567976261488042",type:"guidance",finding:"El aviso del 2 de septiembre retira el artículo de Ariely y Wertenbroch de 2002 sobre plazos, ante dudas sobre la fiabilidad y autenticidad de los datos.",limitation:"Los resultados retirados no respaldan una técnica. El aviso tampoco demuestra que todos los plazos o puntos de revisión personales sean ineficaces."},{id:"procrastination-pomodoro",title:"Cirillo · Origen de la técnica Pomodoro",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"El creador describe una rutina con temporizador que suele enseñarse con bloques de trabajo de 25 minutos y pausas breves.",limitation:"Descripción del creador, no evidencia independiente de eficacia. Este relato no demuestra que el horario exacto o la rutina de ODA funcionen."},{id:"if-then-plans",title:"Gollwitzer y Sheeran · 2006 · Metaanálisis de planes si-entonces",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"En 94 pruebas independientes, los planes concretos si-entonces mejoraron, en promedio, el logro de metas. El efecto estandarizado histórico fue d = 0.65.",limitation:"Estudios antiguos y variados. No significa un 65 por ciento más de éxito ni un efecto específico sobre procrastinación. El ejercicio breve de ODA no se evaluó."},{id:"self-forgiveness",title:"Wohl, Pychyl y Bennett · 2010 · Perdonarse y procrastinación",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 estudiantes de primer año, evaluados antes de dos exámenes parciales, mostraron una relación entre perdonarse más y postergar menos el estudio del examen posterior.",limitation:"Un grupo de un solo curso, con diseño observacional. No se demostró que una frase causara cambios ni que se repararan consecuencias. El reclutamiento inicial y los abandonos siguen sin verificarse."},{id:"procrastination-pomodoro-breaks",title:"Biwer y colaboradores · 2023 · Pausas fijas y elegidas",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 estudiantes compararon pausas elegidas con horarios 24/6 y 12/3. Los horarios fijos tuvieron beneficios subjetivos; no se informó una diferencia significativa en tareas terminadas.",limitation:"Un solo día de estudio autónomo y muestra pequeña; acceso únicamente al resumen. No hallar significación no demuestra igual producción, reducción duradera de procrastinación ni un horario 25/5 óptimo."},{id:"P18",title:"Breines y Chen · 2012 · Escribir con comprensión y ganas de reparar",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"En el experimento 2, escribir con comprensión aumentó la motivación declarada por universitarios para reparar un error y evitar repetirlo.",limitation:"100 personas reclutadas, 91 analizadas. No se midió reparación realizada, cambio duradero ni reducción de procrastinación. ODA añade una acción de reparación independiente."}],t=[{schemaVersion:2,revision:2,id:"procrastination-1",courseId:"procrastination",locale:"es",title:"Lo que postergas ya te está costando",goal:"Da un paso útil en una tarea pendiente tras comprobar si puedes evitar la demora.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Ese reporte de gastos sigue pendiente. ¿Cuánto te costará dejarlo para después?",reason:{id:"procrastination-1-delay-cost-reason",label:"¿Qué te costó la última demora? ¿Era necesario esperar?",kind:"text",maxLength:160,optional:!0,suggestions:["Faltaba información necesaria","Evité registrarlo; se acumuló trabajo","Primero descansé o atendí algo urgente"]},why:{id:"procrastination-1-why",label:"¿Para qué sirve esta tarea o qué te cuesta postergarla?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Procrastinar es dejar para después algo que pensabas hacer, aun sabiendo que la demora puede empeorar las cosas. Descansar, atender una prioridad mayor o esperar recursos puede justificar una pausa. Mira cuál es tu situación antes de llamarte flojo.","Una explicación es que evitar una tarea desagradable te alivia ahora y te cobra después. Es un modelo, no explica cada demora. Nombra la emoción o el impedimento concreto. Si puedes dar un paso seguro y útil, haz una parte aunque siga la incomodidad. Sentirte mejor es opcional; lo que pruebas es la acción."],example:{title:"El recibo de Sofía",text:"A las 3 p. m., Sofía sigue evitando su reporte porque le faltan dos recibos. Revisa qué permite la política y registra uno que sí tiene. Sigue sintiendo vergüenza. Anota lo registrado y la duda pendiente. El reporte no está terminado, pero ya no considera que todo esté bloqueado."}},move:{invitation:"Elige un registro, una frase o una consulta que sirva para tu tarea pendiente.",instructions:["Comprueba si esperar protege una necesidad real.","Elige un ejemplo solo si encaja con tu tarea."],prompts:[{id:"procrastination-1-0",label:"¿Qué parte incomoda o está realmente bloqueada?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Registrar un recibo en mi reporte","Escribir una frase útil para mi tarea","Consultar una regla que frena mi tarea"],minimum:["Registrar un recibo que tengo","Escribir una frase que pueda usar","Enviar una pregunta concreta sobre la regla"],cue:["Al terminar mi próxima pausa laboral","Al retirar el plato de la cena","Cuando una regla poco clara frene mi tarea"],place:["En mi escritorio del trabajo","En la mesa de la cocina","En el chat adecuado, si es seguro"],minutes:[2,5,1],fallback:["Empezar con un recibo que tengo","Escribir un borrador; marcar la duda","Consultar a otra persona disponible si hace falta"],observation:["Lo que registré de verdad","La frase escrita y las dudas pendientes","La pregunta enviada y cualquier respuesta"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",cue:"Al terminar mi próxima pausa laboral",place:"En mi escritorio del trabajo",fallback:"Empezar con un recibo que tengo",observation:"Lo que registré de verdad",minutes:2},{action:"Escribir una frase útil para mi tarea",minimum:"Escribir una frase que pueda usar",cue:"Al retirar el plato de la cena",place:"En la mesa de la cocina",fallback:"Escribir un borrador; marcar la duda",observation:"La frase escrita y las dudas pendientes",minutes:2},{action:"Consultar una regla que frena mi tarea",minimum:"Enviar una pregunta concreta sobre la regla",cue:"Cuando una regla poco clara frene mi tarea",place:"En el chat adecuado, si es seguro",fallback:"Consultar a otra persona disponible si hace falta",observation:"La pregunta enviada y cualquier respuesta",minutes:2,kind:"support"}]},suggested:{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",minutes:2,cueHint:"Al terminar mi próxima pausa laboral",placeHint:"En mi escritorio del trabajo",obstacleHint:"Falta información o quiero evitar la tarea",fallbackHint:"Empezar con un recibo que tengo",observationHint:"Lo que registré de verdad",requiresChoice:!0},stopRule:"No postergues obligaciones urgentes de salud, seguridad o contratos para hacer este experimento.",accessibleAlternative:"Usa herramientas de asistencia, pide información o elige apoyo si la tarea está bloqueada."},result:{question:"¿Hiciste la pequeña parte útil que elegiste?",observationPrompt:"¿Qué hiciste y qué siguió bloqueado?"},judgment:{primary:{id:"procrastination-1-decision",scenario:"Sofía tiene dos minutos libres y la plantilla del reporte. Faltan dos recibos, pero la política permite registrar los disponibles.",question:"¿Qué paso ayuda con la demora?",options:[{id:"procrastination-1-sort",text:"Ordenar todos los recibos por fecha para facilitar la próxima sesión con el reporte.",feedback:"Ordenarlos puede servir después. Aquí ya se puede registrar un recibo. Registra uno ahora y aclara la regla sobre los faltantes sin esperar a tenerlo todo organizado."},{id:"procrastination-1-enter",text:"Revisar la regla sobre recibos faltantes y registrar uno disponible, aunque siga sintiendo vergüenza.",feedback:"Esto aclara la incertidumbre y produce trabajo en el tiempo disponible. La vergüenza no borra lo registrado. Anota qué cambió y qué información todavía necesitas."},{id:"procrastination-1-wait",text:"Reservar mañana una sesión más larga para poder terminar todo el reporte de una vez.",feedback:"Quizá necesite más tiempo para terminar. Eso no resuelve el comienzo que puede hacer hoy. Usa estos minutos para un recibo y programa el trabajo restante."}],bestOptionId:"procrastination-1-enter"}},carry:{takeaway:"Nombra el obstáculo, revisa la necesidad y da un paso útil.",followUp:{questionId:"procrastination-1-return",question:"¿Te frenó la incomodidad o seguía faltando algo necesario?",observationPrompt:"¿Qué hiciste y qué siguió bloqueado?",adjustmentPrompt:"¿Qué ajuste ayudaría a que tu próximo intento encaje mejor?"}},goDeeper:{sections:[{heading:"Una demora no define quién eres",paragraphs:["La revisión de Steel de 2007 reunió 691 correlaciones de 216 trabajos. Las tareas desagradables se asociaron con procrastinación, igual que un menor autocontrol y menor confianza para hacerlas. Esas relaciones no establecen qué causa tu demora. Buena parte de los estudios incluía estudiantes. Sus estimaciones antiguas de frecuencia no representan las tasas actuales. [P01]","La relación con la intención de trabajar fue de -0.03, con un intervalo que incluía cero. Ese promedio casi nulo no demuestra que todos tengan suficientes ganas, tiempo, apoyo o recursos. Mira tu tarea concreta: ¿puedes actuar, tienes otra responsabilidad, necesitas una adaptación o hay motivo para detenerte? Decide según esos hechos, sin convertirlos en un juicio sobre tu carácter."]},{heading:"Alivio ahora, costo después",paragraphs:["Sirois y Pychyl proponen un modelo de alivio emocional: una tarea desagradable puede llevarte a evitarla; evitarla puede darte alivio inmediato y dejarte trabajo pendiente para después. Su artículo de 2013 es una revisión teórica narrativa, no una prueba aleatorizada de ese ciclo ni un tratamiento. No demuestra que notar una emoción sea mejor que planear pasos concretos. [P02]","Nombrar la emoción y hacer una parte de la tarea es una adaptación de ODA. No tienes que confesar nada ni sentir más calma después. Prueba con una tarea cotidiana y segura. Si falta información, una consulta concreta puede ser útil. Si primero necesitas descanso, protección o atender una urgencia, registra esa decisión con honestidad. Las lecciones siguientes ajustan el plan de esta misma tarea según tus intentos. No te piden buscar un fracaso nuevo cada día."]}],sourceIds:["P01","P02"]}},{schemaVersion:2,revision:2,id:"procrastination-2",courseId:"procrastination",locale:"es",title:"¿Sigues preparando? Haz una parte que sirva.",goal:"Haz una parte útil de la misma tarea y termina dentro de tu tiempo disponible.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Otra sesión para prepararte? Esta vez deja hecha una parte que puedas usar.",reason:{id:"procrastination-2-preparation-output-reason",label:"¿Qué produjo tu última preparación y qué parte útil sigue faltando?",kind:"text",maxLength:160,optional:!0,suggestions:["Materiales listos; ninguna frase escrita","Falta una instrucción necesaria","Un recibo registrado; falta el siguiente"]},why:{id:"procrastination-2-why",label:"¿Qué podrías hacer después de terminar una parte útil?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sigue con la tarea que elegiste. Define lo que harás y lo que quedará hecho: registrar un recibo, traducir una frase o responder una pregunta necesaria. Abrir el archivo es preparar; añadir una parte útil es trabajar. Prepararte puede ser necesario. Llámalo así cuando eso sea lo que hagas.","Un plan concreto une una ocasión disponible con lo que decides hacer. La investigación apoya esa estrategia general, no una dosis mágica de dos minutos. Elige una parte que quepa en tu tiempo y termina ahí si lo necesitas. La tarea puede seguir siendo desagradable. Anota lo hecho sin exigir sentirte mejor."],example:{title:"El siguiente recibo de Sofía",text:"El martes, después de su pausa para tomar café, Sofía tiene cinco minutos para el mismo reporte. Piensa en reorganizar sus carpetas, pero registra otro recibo. Hay una categoría que no entiende y la marca para consultarla. Termina al llegar a su límite. Ya hay dos registros; el reporte sigue pendiente."}},move:{invitation:"Conserva tu tarea y la parte elegida. Trabaja dentro del tiempo disponible.",instructions:["Conserva la acción; cambia el mínimo solo si eliges otra parte.","Ajusta “Si hay un obstáculo” y “¿Qué observarás?” a esa parte."],prompts:[],suggestions:{action:["Registrar un recibo en mi reporte","Traducir una frase del documento","Responder una pregunta necesaria de la tarea"],minimum:["Registrar un recibo que tengo","Traducir una frase en borrador","Escribir una respuesta útil"],cue:["Al terminar mi próxima pausa laboral","En mi próximo horario reservado para esta tarea","Al retirar el plato de la cena"],place:["En mi escritorio del trabajo","En una mesa de trabajo accesible","En la mesa de la cocina"],minutes:[2,5,10],fallback:["Dejar las carpetas como están; registrar otro recibo","Marcar un término dudoso y terminar la frase","Escribir lo conocido y consultar lo faltante"],observation:["El recibo registrado y la categoría dudosa","La frase traducida y el término dudoso","La respuesta escrita y el dato faltante"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",cue:"Al terminar mi próxima pausa laboral",place:"En mi escritorio del trabajo",fallback:"Dejar las carpetas como están; registrar otro recibo",observation:"El recibo registrado y la categoría dudosa",minutes:2},{action:"Traducir una frase del documento",minimum:"Traducir una frase en borrador",cue:"En mi próximo horario reservado para esta tarea",place:"En una mesa de trabajo accesible",fallback:"Marcar un término dudoso y terminar la frase",observation:"La frase traducida y el término dudoso",minutes:2},{action:"Responder una pregunta necesaria de la tarea",minimum:"Escribir una respuesta útil",cue:"Al retirar el plato de la cena",place:"En la mesa de la cocina",fallback:"Escribir lo conocido y consultar lo faltante",observation:"La respuesta escrita y el dato faltante",minutes:2}]},suggested:{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",minutes:2,cueHint:"Al terminar mi próxima pausa laboral",placeHint:"En mi escritorio del trabajo",obstacleHint:"Sigo mejorando la preparación sin hacer la tarea",fallbackHint:"Dejar las carpetas como están; registrar otro recibo",observationHint:"El recibo registrado y la categoría dudosa"},stopRule:"Detente ante responsabilidades urgentes o una tarea insegura. Mantén disponibles los contactos necesarios.",accessibleAlternative:"Dicta, escribe, usa herramientas de asistencia o pide un recurso concreto que te falte."},result:{question:"¿Dejaste hecha la parte útil que elegiste?",observationPrompt:"¿Qué trabajo quedó hecho y qué fue preparación?"},judgment:{primary:{id:"procrastination-2-decision",scenario:"Carlos tiene dos minutos antes de una cita. El archivo del contrato está listo y sabe qué frase inicia la primera sección.",question:"¿Qué comienzo aprovecha esos minutos?",options:[{id:"procrastination-2-timer",text:"Comparar dos ajustes del temporizador y elegir uno que sirva para traducir todo el contrato.",feedback:"Un temporizador puede organizar una sesión posterior, pero comparar ajustes no produce una traducción ahora. El archivo y la frase están listos. Usa estos minutos para traducirla en borrador."},{id:"procrastination-2-outline",text:"Esbozar el orden de toda la traducción para que el resto del contrato resulte menos confuso.",feedback:"Un esquema puede ayudar si no sabes por dónde seguir. Carlos ya sabe qué frase toca. Planear toda la secuencia sustituiría trabajo disponible por más preparación."},{id:"procrastination-2-unit",text:"Traducir la primera frase, marcar un término dudoso y detenerse para ir a su cita.",feedback:"Esto deja un borrador útil y señala la duda, sin dar el contrato por terminado. Puede salir a tiempo y revisar el término marcado en la próxima sesión."}],bestOptionId:"procrastination-2-unit"}},carry:{takeaway:"Un comienzo pequeño hace avanzar la tarea si deja trabajo que puedas usar.",followUp:{questionId:"procrastination-2-return",question:"¿Tu mínimo produjo trabajo útil o lo sustituiste por preparación?",observationPrompt:"¿Qué trabajo quedó hecho y qué fue preparación?",adjustmentPrompt:"¿Qué ajuste ayudaría a que tu próximo intento encaje mejor?"}},goDeeper:{sections:[{heading:"La señal ayuda; dos minutos es una elección",paragraphs:["El metaanálisis de Gollwitzer y Sheeran de 2006 reunió 94 pruebas independientes de planes si-entonces. Estos planes concretan una situación reconocible y una respuesta elegida de antemano. En promedio, mejoraron el logro de metas en distintos entornos. El efecto estandarizado histórico de 0.65 no significa un 65 por ciento más de éxito ni predice tu resultado. [P03]","Esta lección usa esa unión entre señal y acción para una tarea cotidiana. Su duración breve y el mínimo de una parte son decisiones de diseño, no una dosis óptima demostrada. Esa parte debe servir a la tarea. Leer instrucciones puede ser preparación si tu meta es escribir; redactar una frase ya es escribir. Ambas opciones pueden ser adecuadas, pero distínguelas. Termina cuando se acabe tu tiempo disponible. Decide si ampliar después según lo hecho, la accesibilidad y tus obligaciones, sin exigir que empezar sea fácil."]},{heading:"Usar bloques con temporizador es opcional",paragraphs:["Biwer y colaboradores compararon pausas elegidas libremente con bloques de estudio de 24 minutos y pausas de seis, y bloques de 12 minutos con pausas de tres. Los 87 estudiantes participaron durante un día de estudio autónomo. Los horarios fijos tuvieron beneficios subjetivos, como menos cansancio y distracción. No se informó una diferencia estadísticamente significativa en tareas terminadas; eso no prueba una producción igual. [P11]","Una revisión más amplia de pausas de hasta diez minutos encontró beneficios más claros para el cansancio y la energía que para el rendimiento general. No establece un horario 25/5 óptimo. [P12] Si eliges un temporizador, usa un intervalo que encaje con tu situación y compara trabajo realizado y cansancio. Que corra el reloj no significa que hiciste la tarea. Conserva la comunicación urgente y la necesaria por accesibilidad. Descansa cuando lo necesites. No hacen falta un temporizador especial, compras ni toda la rutina Pomodoro."]}],sourceIds:["P03","P11","P12"]}},{schemaVersion:2,revision:2,id:"procrastination-3",courseId:"procrastination",locale:"es",title:"Detecta cuándo abandonas la tarea",goal:"Prueba una respuesta a un obstáculo de tu tarea actual y registra si hizo falta usarla.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Abres el archivo y terminas en el teléfono? Decide qué harás justo ahí.",reason:{id:"procrastination-3-switch-cost-reason",label:"¿Qué ganaste al cambiar de actividad y qué te costó?",kind:"text",maxLength:160,optional:!0,suggestions:["Un contacto necesario interrumpió la tarea","Alivio rápido; la frase quedó sin escribir","Faltaba un dato que necesitaba consultar"]},why:{id:"procrastination-3-why",label:"¿Qué protegerías al seguir con esta tarea?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Mira tu último registro. Encuentra cuándo dejaste de trabajar: tomaste el teléfono al abrir el reporte o paraste ante un dato confuso. Prueba qué harás justo ahí. Decirte “esfuérzate más” no te da un plan. Mantén la misma parte útil que ya habías elegido.","Combinar un resultado deseado, un obstáculo y un plan “si pasa esto, hago esto” muestra beneficios promedio modestos. No garantiza que actúes. Elige según lo que te frena. Una distracción puede requerir cambiar el entorno; la falta de información, una consulta. Las responsabilidades de cuidado, una enfermedad o un trabajo inseguro requieren adaptaciones o apoyo."],example:{title:"Cuando Sofía toma el teléfono",text:"El miércoles, en su tiempo para el reporte, Sofía abre el archivo y toma el teléfono. Su plan dice ponerlo boca abajo y registrar primero un recibo. Lo hace y después responde un mensaje necesario. Anota el registro y que apareció el obstáculo. Más tarde, el teléfono vuelve a distraerla."}},move:{invitation:"Conserva tu tarea y tu mínimo. Prueba qué harás ante el obstáculo observado.",instructions:["Edita “Si hay un obstáculo” según lo que realmente te frenó.","¿Sin registro? Identifica cuándo sueles cambiar de actividad o necesitar información."],prompts:[],suggestions:{action:["Registrar un recibo antes de revisar mensajes","Escribir una frase antes de cambiar de pestaña","Consultar un dato que me falta"],minimum:["Registrar un recibo que tengo","Escribir una frase que pueda usar","Enviar una pregunta concreta"],cue:["Cuando vaya a tomar mi teléfono","Cuando vaya a cambiar de pestaña","Cuando me frene un dato confuso"],place:["En mi escritorio del trabajo","En una mesa de trabajo accesible","En el chat adecuado, si es seguro"],minutes:[2,5,1],fallback:["Poner el teléfono boca abajo; permitir contacto urgente","Dejar cerradas otras pestañas y redactar la frase","Enviar la pregunta por otro canal disponible"],observation:["El obstáculo, mi respuesta y el recibo registrado","La señal, mi respuesta y la frase escrita","El dato confuso y la pregunta enviada"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Registrar un recibo antes de revisar mensajes",minimum:"Registrar un recibo que tengo",cue:"Cuando vaya a tomar mi teléfono",place:"En mi escritorio del trabajo",fallback:"Poner el teléfono boca abajo; permitir contacto urgente",observation:"El obstáculo, mi respuesta y el recibo registrado",minutes:2},{action:"Escribir una frase antes de cambiar de pestaña",minimum:"Escribir una frase que pueda usar",cue:"Cuando vaya a cambiar de pestaña",place:"En una mesa de trabajo accesible",fallback:"Dejar cerradas otras pestañas y redactar la frase",observation:"La señal, mi respuesta y la frase escrita",minutes:2},{action:"Consultar un dato que me falta",minimum:"Enviar una pregunta concreta",cue:"Cuando me frene un dato confuso",place:"En el chat adecuado, si es seguro",fallback:"Enviar la pregunta por otro canal disponible",observation:"El dato confuso y la pregunta enviada",minutes:2}]},suggested:{action:"Registrar un recibo antes de revisar mensajes",minimum:"Registrar un recibo que tengo",minutes:2,cueHint:"Cuando vaya a tomar mi teléfono",placeHint:"En mi escritorio del trabajo",obstacleHint:"Reviso mensajes no urgentes mientras trabajo",fallbackHint:"Poner el teléfono boca abajo; permitir contacto urgente",observationHint:"El obstáculo, mi respuesta y el recibo registrado"},stopRule:"Mantén el contacto urgente o necesario por accesibilidad. Busca apoyo ante condiciones inseguras o inaccesibles.",accessibleAlternative:"Usa un recordatorio accesible, pide un recurso o ensaya identificándolo como preparación."},result:{question:"¿Usaste la respuesta elegida e hiciste tu mínimo?",observationPrompt:"¿Apareció el obstáculo y qué hiciste en ese momento?"},judgment:{primary:{id:"procrastination-3-decision",scenario:"Elena toma el teléfono al abrir su documento de tesis. Tiene el primer artículo y eligió escribir una frase en borrador. No espera ningún contacto urgente.",question:"¿Qué respuesta sirve para este obstáculo?",options:[{id:"procrastination-3-response",text:"Apartar el teléfono, escribir una frase en borrador sobre el artículo y después revisar los mensajes necesarios.",feedback:"Esta opción aborda el momento observado y conserva el mínimo útil. Después permite el contacto necesario. Anota si detectó la señal y qué frase escribió de verdad."},{id:"procrastination-3-later",text:"Programar una sesión más larga el fin de semana para que distraerse hoy afecte menos al capítulo.",feedback:"Más tiempo el fin de semana podría ayudar, pero no cambia la señal que la distrae ahora. Prueba una respuesta posible en este momento antes de añadir una sesión mayor."},{id:"procrastination-3-inspire",text:"Releer la meta de la tesis e imaginar el capítulo terminado antes de decidir qué escribir.",feedback:"Recordar la meta puede orientar. Elena también necesita responder al impulso de tomar el teléfono y escribir una frase. Reflexionar solamente no probaría esa respuesta hoy."}],bestOptionId:"procrastination-3-response"}},carry:{takeaway:"Elige qué hacer ante el obstáculo observado y comprueba si produce trabajo útil.",followUp:{questionId:"procrastination-3-return",question:"¿Detectaste el obstáculo a tiempo y pudiste usar tu respuesta?",observationPrompt:"¿Apareció el obstáculo y qué hiciste en ese momento?",adjustmentPrompt:"¿Qué ajuste ayudaría a que tu próximo intento encaje mejor?"}},goDeeper:{sections:[{heading:"Qué añade planear para un obstáculo",paragraphs:["El contraste mental con intenciones de implementación une un resultado deseado, un obstáculo y una respuesta prevista. Wang y colaboradores reunieron 21 artículos con 24 efectos independientes. Encontraron un beneficio promedio pequeño a moderado para lograr metas. Los resultados variaban y mostraban señales de sesgo de publicación. El método también puede ayudar a abandonar una meta inviable. No te exige superar cualquier impedimento. [P04]","En el ejercicio académico de Oettingen y colaboradores de 2015, los estudiantes consideraban una preocupación importante. Imaginaban el resultado y el obstáculo, elegían una respuesta, fijaban momento y lugar, ensayaban y armaban un calendario semanal. Se midieron horas de actividad previstas, no trabajo realizado. [P10] Tu plan breve para una tarea adulta cambia ese procedimiento. Aquí registras lo que hiciste. Imaginar, ensayar, planear y hacer no son formas equivalentes de avanzar. Tampoco supongas que un plan demostró ser mejor que cinco."]},{heading:"Querer empezar no demuestra que empezaste",paragraphs:["El estudio aleatorizado reciente de Zhou y colaboradores incluyó a 81 universitarios de una universidad privada china. Su resumen accesible informa tareas menos desagradables y mayor disposición a actuar con la estrategia de planificación, frente al pensamiento positivo. Midió disposición a empezar, no inicios ni tareas terminadas que se hubieran verificado. Las ganas no equivalen a hacer. [P09]","Pensar en positivo no es automáticamente inútil, y un obstáculo no tiene por qué ser un defecto tuyo. Este experimento parte del momento en que cambiaste de actividad o del impedimento concreto que registraste. La respuesta útil es reconocible y posible en ese entorno. Si no aparece el obstáculo, la respuesta queda sin probar, no fallida. Si aparece y no puedes responder, cambia el entorno, el tamaño del paso o el apoyo. Conserva la tarea y el rumbo; ajusta la condición que mostró tu registro."]}],sourceIds:["P04","P10","P09"]}},{schemaVersion:2,revision:2,id:"procrastination-4",courseId:"procrastination",locale:"es",title:"¿No cumpliste? Repara lo que puedas.",goal:"Elige reparar, retomar la tarea o pedir apoyo sin prometer lo que no puedes cumplir.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"¿Pasó la fecha de entrega? Di con honestidad qué sigue a quien espera.",reason:{id:"procrastination-4-owed-repair-reason",label:"¿Qué te toca reparar y qué costaría volver a callar o prometer?",kind:"text",maxLength:160,optional:!0,suggestions:["Debo informar cómo va la tarea","No tengo que informar; retomo el trabajo","El contacto es inseguro; busco apoyo"]},why:{id:"procrastination-4-why",label:"¿Qué responsabilidad o límite necesita atención ahora?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Registra con honestidad. Si alguien espera, revisa si debes informar o reparar algo. Di qué falta y qué puedes entregar. Tratarte con comprensión no cambia el plazo, ni borra consecuencias ni justifica prometer más de lo que puedes.","En un experimento, escribir con comprensión aumentó la motivación declarada para reparar un error. No se midió la reparación realizada. Aplica esa diferencia: una frase justa es preparación; enviar información o hacer parte de la tarea es acción. Elige un acto como mínimo y registra los demás por separado. No necesitas sentir que te has perdonado."],example:{title:"Sofía informa con honestidad",text:"El jueves, el reporte de Sofía ya está atrasado. Escribe: “Lo postergué; puedo afrontar lo que me toca”. Elige una reparación: informar a finanzas qué falta y preguntar por los recibos ausentes. Aún no responden. Registra el mensaje enviado. Registrar otro recibo será una acción posterior, no una reparación ya hecha."}},move:{invitation:"Conserva tu tarea. Elige reparar, retomarla de forma útil o pedir apoyo seguro.",instructions:["Revisa qué te toca reparar antes de elegir una acción.","Elige un acto como mínimo y registra los demás por separado."],prompts:[],suggestions:{action:["Informar qué puedo entregar y cuándo","Escribir una parte útil de mi tarea","Pedir ayuda para dividir mi tarea pendiente"],minimum:["Enviar información honesta sobre alcance y plazo","Escribir una frase útil para mi tarea","Enviar una petición para dividir la tarea"],cue:["En mi próxima pausa laboral segura","En mi próximo horario reservado para esta tarea","En mi próxima conversación de apoyo acordada"],place:["En el chat de trabajo que corresponda","En una mesa de trabajo accesible","En un chat seguro para pedir apoyo"],minutes:[5,2,10],fallback:["Informar lo que sé sin prometer plazos inciertos","Redactar lo conocido y marcar un dato faltante","Si no puede, consultar a alguien de confianza"],observation:["El mensaje enviado y cualquier respuesta","La frase que escribí para la tarea","La petición para dividir la tarea y respuesta"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Informar qué puedo entregar y cuándo",minimum:"Enviar información honesta sobre alcance y plazo",cue:"En mi próxima pausa laboral segura",place:"En el chat de trabajo que corresponda",fallback:"Informar lo que sé sin prometer plazos inciertos",observation:"El mensaje enviado y cualquier respuesta",minutes:5},{action:"Escribir una parte útil de mi tarea",minimum:"Escribir una frase útil para mi tarea",cue:"En mi próximo horario reservado para esta tarea",place:"En una mesa de trabajo accesible",fallback:"Redactar lo conocido y marcar un dato faltante",observation:"La frase que escribí para la tarea",minutes:2},{action:"Pedir ayuda para dividir mi tarea pendiente",minimum:"Enviar una petición para dividir la tarea",cue:"En mi próxima conversación de apoyo acordada",place:"En un chat seguro para pedir apoyo",fallback:"Si no puede, consultar a alguien de confianza",observation:"La petición para dividir la tarea y respuesta",minutes:2,kind:"support"}]},suggested:{action:"Informar qué puedo entregar y cuándo",minimum:"Enviar información honesta sobre alcance y plazo",minutes:5,cueHint:"En mi próxima pausa laboral segura",placeHint:"En el chat de trabajo que corresponda",obstacleHint:"Quiero callar o prometer más de lo que puedo",fallbackHint:"Informar lo que sé sin prometer plazos inciertos",observationHint:"El mensaje enviado y cualquier respuesta",requiresChoice:!0},stopRule:"Elige un descuido cotidiano. No te culpes por el daño que otra persona causó. Si el contacto es inseguro, pausa y busca apoyo.",accessibleAlternative:"Usa un mensaje seguro, comunicación asistida o apoyo en lugar de un contacto inseguro."},result:{question:"¿Hiciste la reparación o el regreso a la tarea elegido?",observationPrompt:"¿Qué acto hiciste y qué sigue pendiente?"},judgment:{primary:{id:"procrastination-4-capacity-repair-decision",scenario:"Daniel no entregó el borrador prometido. El equipo necesita saber cómo va. Puede entregar una sección hoy, pero el borrador completo requiere más tiempo.",question:"¿Qué respuesta encaja con su capacidad actual?",options:[{id:"procrastination-4-finish",text:"Terminar primero la sección disponible y esperar para informar al equipo hasta que el borrador dé confianza.",feedback:"Hacer la sección importa, pero el equipo ya está esperando y necesita información actual. Explica con honestidad qué puedes entregar y cuándo; después prepara esa sección."},{id:"procrastination-4-revise-first",text:"Pedir ahora otra fecha para todo el borrador y posponer la sección disponible hasta que acepten el cambio.",feedback:"Quizá haya que renegociar, pero hoy el equipo puede recibir información y una sección útil. Propón plazos realistas para lo restante y entrega lo disponible, salvo que sus necesidades requieran esperar."},{id:"procrastination-4-repair",text:"Reconocer el incumplimiento, proponer alcance y plazos posibles y producir la sección que puede entregar.",feedback:"Esto afronta las consecuencias sin sumar una promesa imposible. Informar y preparar la sección son actos concretos. El equipo decide si acepta: registra su respuesta con honestidad."}],bestOptionId:"procrastination-4-repair"}},carry:{takeaway:"Una frase justa apoya la reparación. Reparar es hacer algo concreto que atienda las consecuencias.",followUp:{questionId:"procrastination-4-chosen-act-return",question:"¿La reparación, el regreso o el apoyo elegido encajó con tu capacidad real?",observationPrompt:"¿Qué hiciste y qué necesita todavía una respuesta?",adjustmentPrompt:"¿Qué ajuste ayudaría a que tu próximo intento encaje mejor?"}},goDeeper:{sections:[{heading:"Tratarte con comprensión y reparar son cosas distintas",paragraphs:["En el experimento de Breines y Chen de 2012, universitarios describieron un acto reciente que consideraban incorrecto y se escribieron con comprensión. Se reclutaron 100 personas y se analizaron 91. Ese grupo declaró más motivación para reparar el error y evitar repetirlo que los grupos de comparación. No se demostró que completaran disculpas o reparaciones ni que redujeran la procrastinación con el tiempo. [P18]","Esta lección usa una frase justa más breve para una tarea cotidiana postergada y añade una acción elegida por separado. Es una adaptación de ODA, no el ejercicio estudiado. Puedes informar de forma segura, corregir un error, hacer una parte acordada, pedir una adaptación o abandonar un plan inadecuado. Registra cuál de esos actos ocurrió. Tu responsabilidad debe corresponder a lo que realmente hiciste. Haber sufrido daño no te obliga a contactar, reconciliarte ni pedir disculpas."]},{heading:"Qué no puede prometer la evidencia sobre perdonarse",paragraphs:["Wohl, Pychyl y Bennett estudiaron a 119 estudiantes de primer año de un curso de psicología. Los evaluaron justo antes de cada uno de dos exámenes parciales. Perdonarse más se relacionó con postergar menos antes del segundo examen. Esa relación observacional no demuestra que perdonarse causara el cambio ni que una frase determinada ayude a retomar una tarea. [P07]","Perdonarte y tratarte con autocompasión son conceptos relacionados, pero distintos. La revisión de Han y Kim de 56 ensayos aleatorizados encontró beneficios limitados sobre el malestar, con riesgo general de sesgo alto. No valida una sola frase como tratamiento ni demuestra que facilite empezar tu próxima tarea. [P08] Puedes probar una descripción justa mientras sigues sintiendo arrepentimiento o frustración. Comprueba si tu próximo compromiso es realista y si reparaste o retomaste la tarea. No se exige una transformación emocional."]}],sourceIds:["P18","P07","P08"]}},{schemaVersion:2,revision:2,id:"procrastination-5",courseId:"procrastination",locale:"es",title:"¿No logras empezar? Ajusta el próximo horario.",goal:"Conserva el plan útil, cambia un obstáculo observado y programa el próximo intento viable.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"¿Unas veces empezaste y otras no? Planea según tus registros.",reason:{id:"procrastination-5-reason",label:"¿Esta tarea aún justifica lo que te cuesta esta semana?",kind:"text",maxLength:160,optional:!0,suggestions:["Seguir cumpliendo un compromiso","Ajustar un plan que sigue fallando","Pedir ayuda con un problema repetido"]},why:{id:"procrastination-5-why",label:"¿Esta tarea aún justifica lo que te cuesta esta semana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Usa la tarea, el rumbo, el mínimo y los intentos guardados. Revisar el progreso puede ayudar a lograr metas, en promedio. Distingue plan, intento y trabajo útil. Sin registro, no sabemos qué pasó. No significa fracaso ni éxito.","Conserva lo que ayudó y cambia una condición que te frenó. Una revisión personal puede seguir siendo un experimento. Para cambiar una fecha prometida hace falta hablar y acordarlo. Guarda tu próxima parte útil; ODA programa la revisión al día siguiente. Si no conoces una señal útil, prueba una ocasión posible. Busca apoyo durante la práctica si postergar te causa daño persistente."],example:{title:"La próxima semana de Sofía",text:"El viernes, Sofía revisa el reporte: tres recibos registrados, una consulta sin respuesta y un horario previsto que no usó. Las pausas laborales sirvieron; a última hora de la noche, no. Reserva otro recibo tras la pausa del lunes y revisa a quién debe informar. El reporte sigue pendiente. El nuevo plan usa esos datos."}},move:{invitation:"Conserva tu tarea y la señal útil. Cambia lo que te bloqueó.",instructions:["¿Sin señal útil registrada? Elige una primera ocasión que sea posible.","Guarda la próxima parte; ODA programa una revisión para el día siguiente."],prompts:[],suggestions:{action:["Registrar un recibo en mi reporte","Escribir una parte útil de mi tarea","Pedir apoyo para cambiar un horario imposible"],minimum:["Registrar un recibo que tengo","Escribir una frase útil para mi tarea","Enviar una petición para ajustar mi horario"],cue:["Al terminar mi próxima pausa laboral disponible","En mi próximo tiempo reservado para escribir","En la próxima conversación acordada sobre horarios"],place:["En mi escritorio del trabajo","En una mesa de trabajo accesible","En un chat seguro para pedir apoyo"],minutes:[2,5,10],fallback:["Usar la pausa laboral disponible de mañana","Usar mañana mi tiempo reservado para escribir","Si no puede, consultar a alguien de confianza"],observation:["El recibo registrado y si pude trabajar allí","La frase escrita y si sirvió ese horario","La petición sobre el horario y cualquier respuesta"],when:[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],bundles:[{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",cue:"Al terminar mi próxima pausa laboral disponible",place:"En mi escritorio del trabajo",fallback:"Usar la pausa laboral disponible de mañana",observation:"El recibo registrado y si pude trabajar allí",minutes:2},{action:"Escribir una parte útil de mi tarea",minimum:"Escribir una frase útil para mi tarea",cue:"En mi próximo tiempo reservado para escribir",place:"En una mesa de trabajo accesible",fallback:"Usar mañana mi tiempo reservado para escribir",observation:"La frase escrita y si sirvió ese horario",minutes:2},{action:"Pedir apoyo para cambiar un horario imposible",minimum:"Enviar una petición para ajustar mi horario",cue:"En la próxima conversación acordada sobre horarios",place:"En un chat seguro para pedir apoyo",fallback:"Si no puede, consultar a alguien de confianza",observation:"La petición sobre el horario y cualquier respuesta",minutes:2,kind:"support"}]},suggested:{action:"Registrar un recibo en mi reporte",minimum:"Registrar un recibo que tengo",minutes:2,cueHint:"Al terminar mi próxima pausa laboral disponible",placeHint:"En mi escritorio del trabajo",obstacleHint:"Quizá no pueda usar el horario propuesto",fallbackHint:"Usar la pausa laboral disponible de mañana",observationHint:"El recibo registrado y si pude trabajar allí"},stopRule:"Busca apoyo ahora si la demora daña tu vida. Las obligaciones urgentes necesitan la acción adecuada.",accessibleAlternative:"Elige trabajo con asistencia, una petición de apoyo, un límite viable o una pausa."},result:{question:"¿Hiciste la siguiente pequeña parte que elegiste?",observationPrompt:"¿Qué trabajo útil o petición de apoyo hiciste?"},judgment:{primary:{id:"procrastination-5-decision",scenario:"Nadia escribió frases para su ensayo el martes. El jueves no pudo usar el horario previsto. Le sirvió la revisión acordada con una amiga. El plazo de la solicitud sigue fijo.",question:"¿Qué conservar o cambiar la próxima semana?",options:[{id:"procrastination-5-more",text:"Añadir revisiones personales diarias para que cada comienzo previsto tenga una consecuencia cercana y una meta clara.",feedback:"Más revisiones podrían aportar estructura, pero el registro muestra un horario imposible el jueves. Conserva la revisión útil y cambia ese horario antes de añadir presión diaria."},{id:"procrastination-5-adjust",text:"Conservar la revisión con su amiga, cambiar la señal del jueves y comparar intentos y frases escritas la próxima semana.",feedback:"Esto usa lo que funcionó y mantiene visible la fecha real. El siguiente registro debe mostrar intentos y escritura útil. Habla con los demás si cambia algún compromiso acordado."},{id:"procrastination-5-remove",text:"Quitar las revisiones personales y guiarse solo por la fecha final mientras siga incierta la evidencia sobre plazos.",feedback:"La evidencia general incierta no borra la revisión que le sirvió a Nadia. Consérvala como experimento elegido, sin llamarla cura demostrada, y resuelve directamente el problema de horario."}],bestOptionId:"procrastination-5-adjust"}},carry:{takeaway:"Conserva lo que sirvió, cambia lo que te frenó y registra el trabajo real.",followUp:{questionId:"procrastination-5-work-or-support-return",question:"¿Hiciste el próximo paso de trabajo o apoyo en la ocasión elegida?",observationPrompt:"¿Qué trabajo o petición hiciste y sirvió la señal?",adjustmentPrompt:"¿Qué ajuste ayudaría a que tu próximo intento encaje mejor?"}},goDeeper:{sections:[{heading:"Usa tus registros, no una colección de técnicas",paragraphs:["Harkin y colaboradores reunieron 138 estudios aleatorizados sobre seguimiento del progreso en metas diversas. Las intervenciones mejoraron el logro de metas, en promedio. En análisis adicionales, registrar y comunicar se asociaron con efectos mayores. Esa relación no demuestra que cada formato para compartir cause mejoras. No hace falta divulgarlo públicamente. Este plan programa una revisión en ODA al día siguiente. Comparar semanas es opcional en tu calendario privado; aquí no se guarda una segunda cita. [P13]","Usa tus intentos fechados para responder una pregunta concreta: ¿la señal, el mínimo y la respuesta elegidos permitieron trabajo útil? Terminar una parte no significa terminar toda la tarea. Si un obstáculo no apareció, la respuesta queda sin probar. Conserva visibles los huecos del historial. La próxima semana, mantén lo que encajó y cambia el obstáculo que muestra el registro. Si la tarea ya no sirve a tus responsabilidades o al rumbo elegido, considera renegociar, pausar o detenerte antes de añadir otra técnica."]},{heading:"Apoyo y plazos con límites honestos",paragraphs:["La revisión controlada de Rozental y colaboradores incluyó 12 estudios con 718 participantes, principalmente estudiantes. Las intervenciones psicológicas redujeron, en promedio, la procrastinación declarada frente a controles sin intervención activa. La calidad, los métodos diversos y los pocos estudios por tratamiento hacen provisionales los hallazgos. No demuestran que ODA funcione ni que todo formato necesite aplicación profesional. Puedes buscar evaluación o apoyo si el impacto lo justifica, mientras haces este experimento. [P05]","El conocido artículo de Ariely y Wertenbroch sobre plazos autoimpuestos fue retirado en septiembre de 2026 por dudas sobre la fiabilidad y autenticidad de los datos. Sus resultados no validan una técnica. El aviso tampoco demuestra que toda revisión personal falle. [P15] Tu recordatorio puede seguir siendo un experimento voluntario. Una entrega laboral, académica o para un cliente es un compromiso real: habla y busca acuerdo antes de cambiarla. La presión autoimpuesta no sustituye actuar ante obligaciones urgentes de salud, seguridad, legales o contractuales."]}],sourceIds:["P13","P05","P15"]}}],u=[{id:"1552360708-ebcdf76845ac",alt:"Mujer sentada junto a una ventana, pensativa"},{id:"1448387473223-5c37445527e7",alt:"Un pie que sube al primer escalón"},{id:"1553044020-8c90843adf96",alt:"Notas adhesivas amarillas y una pluma"},{id:"1778958619388-b529cc4e78e8",alt:"Mujer joven tomando té junto a una ventana"},{id:"1506784983877-45594efa4cbe",alt:"Taza de café sobre una agenda abierta"}],s=[1,2,0,2,1],l={id:"procrastination",title:"¿Sigues postergando? Haz una parte que sirva.",subtitle:"Una tarea pendiente. Cinco lecciones para hacer trabajo útil, afrontar el obstáculo y volver con un plan honesto.",description:"Deja de juzgarte por una tarea pendiente. Haz una parte útil, registra el obstáculo y repara o ajusta lo que tu semana necesita.",scope:"Habilidades para la procrastinación cotidiana; no es terapia. Si postergar se acompaña de ansiedad intensa, ánimo bajo persistente o dificultades de atención y afecta claramente tu vida, puedes buscar apoyo profesional.",outcome:"Una parte útil de tu tarea, una respuesta al obstáculo y una próxima fecha viable.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Mujer trabajando con una computadora portátil en un escritorio rodeado de plantas"},lang:"es",lessons:t.map((a,o)=>{const e=a.judgment.primary,i=e.options.find(r=>r.id===e.bestOptionId),n=e.options.filter(r=>r.id!==e.bestOptionId);return n.splice(s[o],0,i),{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,practice:[...a.move.instructions,"Vuelve aquí y registra lo que pasó de verdad."],reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:n.map(r=>r.text),correct:s[o],feedback:i.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,deeper:a.goDeeper.sections,example:a.idea.example,photo:u[o]}})},d=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,LESSONS_V2:t,SOURCES:c},Symbol.toStringTag,{value:"Module"}));export{d as p};
